   562	/// The message types that can be sent to the app thread.
   563	pub const Message = union(enum) {
   564	    // Open the configuration file
   565	    open_config: OpenConfig,
   566	
   567	    /// Create a new terminal window.
   568	    new_window: NewWindow,
   569	
   570	    /// Close a surface. This notifies the runtime that a surface
   571	    /// should close.
   572	    close: *Surface,
   573	
   574	    /// Quit
   575	    quit: void,
   576	
   577	    /// A message for a specific surface.
   578	    surface_message: struct {
   579	        surface: *Surface,
   580	        message: apprt.surface.Message,
   581	    },
   582	
   583	    const NewWindow = struct {
   584	        /// The parent surface
   585	        parent: ?*Surface = null,
   586	    };
   587	
   588	    pub const OpenConfig = enum {
   589	        /// Open the config in the OS default editor.
   590	        os_open,
   591	        /// Open the config in a new window using $EDITOR or $VISUAL
   592	        new_window,
   593	    };
   594	};
