     8	/// Returns a blocking queue implementation for type T.
     9	///
    10	/// This is tailor made for ghostty usage so it isn't meant to be maximally
    11	/// generic, but I'm happy to make it more generic over time. Traits of this
    12	/// queue that are specific to our usage:
    13	///
    14	///   - Fixed size. We expect our queue to quickly drain and also not be
    15	///     too large so we prefer a fixed size queue for now.
    16	///   - No blocking pop. We use an external event loop mechanism such as
    17	///     eventfd to notify our waiter that there is no data available so
    18	///     we don't need to implement a blocking pop.
    19	///   - Drain function. Most queues usually pop one at a time. We have
    20	///     a mechanism for draining since on every IO loop our TTY drains
    21	///     the full queue so we can get rid of the overhead of a ton of
    22	///     locks and bounds checking and do a one-time drain.
    23	///
    24	/// One key usage pattern is that our blocking queues are single producer
    25	/// single consumer (SPSC). This should let us do some interesting optimizations
    26	/// in the future. At the time of writing this, the blocking queue implementation
    27	/// is purposely naive to build something quickly, but we should benchmark
    28	/// and make this more optimized as necessary.
    29	pub fn BlockingQueue(
    30	    comptime T: type,
    31	    comptime capacity: usize,
    32	) type {
    33	    return struct {
    34	        const Self = @This();
    35	
    36	        // The type we use for queue size types. We can optimize this
    37	        // in the future to be the correct bit-size for our preallocated
    38	        // size for this queue.
    39	        pub const Size = u32;
    40	
    41	        // The bounds of this queue. We recast this to Size so we can do math.
    42	        const bounds: Size = @intCast(capacity);
    43	
    44	        /// Specifies the timeout for an operation.
    45	        pub const Timeout = union(enum) {
    46	            /// Fail instantly (non-blocking).
    47	            instant: void,
    48	
    49	            /// Run forever or until interrupted
    50	            forever: void,
    51	
    52	            /// Nanoseconds
    53	            ns: u64,
    54	        };
    55	
    56	        /// Our data. The values are undefined until they are written.
    57	        data: [bounds]T = undefined,
    58	
    59	        /// The next location to write (next empty loc) and next location
    60	        /// to read (next non-empty loc). The number of written elements.
    61	        write: Size = 0,
    62	        read: Size = 0,
    63	        len: Size = 0,
    64	
    65	        /// The big mutex that must be held to read/write.
    66	        mutex: std.Io.Mutex = .init,
    67	
